import{_ as t,o as i,c as o,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"CephDeveloperMonthly2023-10-04","description":"","frontmatter":{"title":"CephDeveloperMonthly2023-10-04","date":"2023-10-04T00:00:00.000Z","updated":"2023-10-05T00:00:00.000Z","tags":["Ceph","分布式存储","审计模块","去重功能","资源消耗","性能测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Developer_Monthly_2023-10-04.md","filePath":"posts/2023/Ceph_Developer_Monthly_2023-10-04.md","lastUpdated":1780459816000}'),r={name:"posts/2023/Ceph_Developer_Monthly_2023-10-04.md"};function a(n,l,s,h,g,u){return i(),o("div",null,[...l[0]||(l[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议基本信息" tabindex="-1">会议基本信息 <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;会议基本信息&quot;">​</a></h4><ul><li><strong>日期与时间</strong>: 2023年10月4日</li><li><strong>参会人员</strong>: CDM团队成员</li><li><strong>会议平台</strong>: Google Meet</li><li><strong>记录人员</strong>: [记录人员姓名]</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>审计模块的创建请求（RFE）</strong></p><ul><li><strong>背景</strong>: CFS团队希望在RADOS中持久化存储审计日志。</li><li><strong>当前问题</strong>: 现有的审计日志可能被删除或丢失。</li><li><strong>提议解决方案</strong>: 开发新的RADOS管理模块，用于持久化存储审计日志条目。</li><li><strong>讨论点</strong>: <ul><li>用户如何选择需要保存的审计日志。</li><li>权限和API设计问题。</li><li>保留策略的配置。</li></ul></li><li><strong>共识</strong>: 团队普遍认为该功能有其价值，但需要进一步明确细节和实施方案。</li></ul></li><li><p><strong>去重功能的改进</strong></p><ul><li><strong>当前状态</strong>: 已有初步的去重实现，但存在效率问题。</li><li><strong>主要问题</strong>: 小数据块的存储效率低下，无法有效处理大量重复数据块。</li><li><strong>提议解决方案</strong>: 设计一个新的去重机制，通过打包小数据块到大对象中来提高效率。</li><li><strong>讨论点</strong>: <ul><li>如何设计有效的索引机制。</li><li>去重过程的性能和资源消耗。</li><li>如何平衡在线和离线工具的需求。</li></ul></li><li><strong>共识</strong>: 需要进一步研究和测试，以确定最佳实施方案。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li><strong>审计模块</strong>: 继续推进审计模块的开发，明确用户需求和实施细节。</li><li><strong>去重功能</strong>: 开发新的去重机制，进行详细的性能测试和资源评估。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>审计模块</strong>: <ul><li>明确用户选择审计日志的机制。</li><li>设计API和权限检查。</li><li>配置保留策略。</li></ul></li><li><strong>去重功能</strong>: <ul><li>开发和测试新的去重机制。</li><li>评估性能和资源消耗。</li><li>发布测试工具和结果，收集社区反馈。</li></ul></li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>会议记录和讨论结果将分享给未能参加会议的团队成员。</li><li>下一次会议将在下个月举行。</li></ul><h4 id="会议结束语" tabindex="-1">会议结束语 <a class="header-anchor" href="#会议结束语" aria-label="Permalink to &quot;会议结束语&quot;">​</a></h4><p>感谢所有参与者的贡献和讨论，期待在下一次会议中看到更多的进展和成果。再见！</p>',13)])])}const _=t(r,[["render",a]]);export{p as __pageData,_ as default};
